INSERT INTO event VALUES(96,3,6,'context.blob',1,1767225696000,'{"payload":{"digest":"05a013fc06a93e045bebd556939c491d97dbe003416d9b472a494c0696bacc11","value":"{\"sections\":{\"core plugin\":\"For math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\",\"memory-workflow plugin\":\"<memory_tool_instructions>\\nPinned memories apply to every session unless the user forbids memory use, and nothing loads them for you. At session start, `view` the `/memories` directory to find entries marked [pinned]. If the listing is truncated, continue until you have seen every [pinned] entry. Then `view` each pinned file so its content applies, regardless of how self-contained the request looks. Pinned entries are the core reusable insights (techniques, strategies, pitfalls) accumulated across sessions. The directory listing alone does not load their content. Beyond pinned entries, use memory when the request may depend on prior sessions, durable user preferences, or shared agent context. For a self-contained request, do not read unpinned memory files or write memory merely because the tool is available. Listing the directory is still appropriate because it is needed to find pinned entries.\\n\\nYour memory persists across conversations. When memory is in play, record durable progress, decisions, and user preferences (writing style, conventions, formatting, workflow). Keep the folder current and organized by updating, renaming, or deleting files rather than duplicating them. Do not store what the workspace files already state. Use `pin` only for long-term reusable insights, never task-specific progress notes. Use `unpin` for entries that no longer earn their place.\\n</memory_tool_instructions>\",\"tool-call\":\"Independent tool calls may be issued together in one response. Sequence only calls that depend on an earlier result.\"},\"tools\":[\"read_file\",\"glob\",\"grep\",\"arxiv_search\",\"memory\",\"context\"]}"}}');
INSERT INTO event VALUES(97,3,7,'context.blob',1,1767225697000,'{"payload":{"digest":"6e418fb15040d4b29421ec9a2946acb53ce350ccb8c8fb463b9303d660482e99","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(98,3,8,'context.blob',1,1767225698000,'{"payload":{"digest":"ec10868c62c153531d218406d87ce48fcfde705a2d58b4bda0dc1d9d8757d3cf","value":"{\"description\":\"Find files matching glob patterns (e.g., \\\"**/*.md\\\", \\\"src/**/*.ts\\\"). Returns paths sorted by modification time.\",\"name\":\"glob\",\"parameters\":{\"properties\":{\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Directory to search within. Defaults to the workspace root.\"},\"pattern\":{\"description\":\"Glob pattern to match, such as \\\"**/*.md\\\" or \\\"src/**/*.ts\\\".\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(99,3,9,'context.blob',1,1767225699000,'{"payload":{"digest":"ff7eb1a009b970c6037d780078c1e86154afc97118014fb205a4d5e34efbe134","value":"{\"description\":\"Search file contents using regex patterns. For surrounding lines use -C with output_mode \\\"content\\\".\",\"name\":\"grep\",\"parameters\":{\"properties\":{\"-A\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context AFTER each match (only with output_mode \\\"content\\\").\"},\"-B\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context BEFORE each match (only with output_mode \\\"content\\\").\"},\"-C\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context before AND after each match.\"},\"-i\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Case-insensitive search.\"},\"-n\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Show line numbers.\"},\"glob\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Glob filter for file names (e.g. \\\"*.md\\\").\"},\"head_limit\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Limit to first N results.\"},\"literal\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Exact string, not regex.\"},\"multiline\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Enable multiline matching (pattern can span lines).\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Skip first N results.\"},\"output_mode\":{\"anyOf\":[{\"enum\":[\"content\",\"files_with_matches\",\"count\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Must be \\\"content\\\", \\\"files_with_matches\\\", or \\\"count\\\". For context lines around matches, use -C instead.\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"File or directory to search in.\"},\"pattern\":{\"description\":\"Regex pattern.\",\"minLength\":1,\"type\":\"string\"},\"type\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Ripgrep file type filter (e.g. \\\"tex\\\", \\\"py\\\").\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(100,3,10,'context.blob',1,1767225700000,'{"payload":{"digest":"a146ff8f2543030ca3e39ea816c65cdc53c5c5f78cf9c8d027dda8a80b5a2601","value":"{\"description\":\"Search arXiv for papers and return basic metadata for each hit. Use field=\\\"author\\\" for author name searches.\",\"name\":\"arxiv_search\",\"parameters\":{\"properties\":{\"categories\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional arXiv category filters, exactly as arXiv spells them, such as \\\"math.NT\\\", \\\"cs.AI\\\" or \\\"quant-ph\\\". A paper matches when it is in all of them.\"},\"field\":{\"anyOf\":[{\"enum\":[\"all\",\"author\",\"title\",\"abstract\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Search field: \\\"author\\\" for author names, \\\"title\\\" for paper titles, \\\"abstract\\\" for abstracts, \\\"all\\\" (default) for all fields\"},\"maxResults\":{\"anyOf\":[{\"exclusiveMinimum\":0,\"maximum\":50,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Maximum number of papers to return.\"},\"query\":{\"description\":\"Search query terms, title text, or author names.\",\"type\":\"string\"},\"sortBy\":{\"anyOf\":[{\"enum\":[\"relevance\",\"lastUpdatedDate\",\"submittedDate\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"arXiv sort field to use.\"},\"sortOrder\":{\"anyOf\":[{\"enum\":[\"ascending\",\"descending\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Sort direction for results.\"},\"start\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based result offset for pagination.\"}},\"required\":[\"query\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(101,3,11,'context.blob',1,1767225701000,'{"payload":{"digest":"2cf24576e72aa687df224a7a5037639917077bc04a67b4fef3ba72649d863a14","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are the ones to read at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"create\\\".\"},\"insert_line\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\".\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\": Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"new_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\" or \\\"insert\\\".\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"old_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\".\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted. With command \\\"create\\\", \\\"str_replace\\\", \\\"insert\\\", \\\"delete\\\", \\\"pin\\\", or \\\"unpin\\\": Path under /memories (e.g. /memories/notes.md).\"},\"view_range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\".\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(102,3,12,'context.blob',1,1767225702000,'{"payload":{"digest":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","value":"{\"description\":\"Read or edit your own context: the messages each of your requests sends.\\n\\n- view: each message with its index, role, kind, estimated tokens and a preview; the window size and the tokens in use; and the replacements this response already asked for.\\n- replace: messages [from, to) are replaced, before your next request, by one message holding `with`. Indices are the view''s, as this response was sent; ranges asked for in one response must not overlap. The range ends at or before the response that makes the call, and keeps each tool call with its results.\\n\\nThe replaced messages stay in the stored history: the person still sees them, and the executions tool, where offered, reads them back (/executions/current/conversation). A replacement ends prompt-cache reuse from its first message on, and any provider-side continuation, so the next request pays full input price for everything after that point. Keep what the user asked of you, in substance.\",\"name\":\"context\",\"parameters\":{\"properties\":{\"action\":{\"anyOf\":[{\"enum\":[\"view\",\"replace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"view\\\": Read the view (the default).\"},\"from\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index of the first message replaced.\"},\"to\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index after the last message replaced.\"},\"with\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": The text that stands in for those messages.\"}},\"type\":\"object\"}}"}}');
