INSERT INTO event VALUES(185,5,33,'script.call',3,1767225785000,'{"payload":{"scriptCallId":"script","seq":0,"callId":"script/0","toolName":"document_context","input":{"intro":"Read the following LaTeX research documents before editing them.","requests":["Edit the documents as the instruction asks, to the extent it asks: a proofread changes wording and formatting only, a polish may rewrite sentences and paragraphs for clarity and flow, and a request for new or expanded content adds it with every derivation step shown. Do not change text the instruction does not concern. Write plain technical English: concrete statements, plain verbs, each point made once.","Review your changes against the original and the instruction, then output the corrected documents. Revert any change the instruction did not ask for. Restore mathematics, equations or reasoning that went missing. Fix notation used before it is defined, and remove sentences that say nothing specific. If a change holds up, leave it alone; if nothing needs fixing, reproduce the documents unchanged."],"revision":0,"critique":null},"replay":"safe","logId":"00000000-0000-4000-8000-000000000032","section":"Revision 1"}}');
