INSERT INTO event VALUES(192,5,40,'script.call',3,1767225792000,'{"payload":{"scriptCallId":"script","seq":1,"callId":"script/1","toolName":"agent","input":{"agentName":"edit","persona":{"prompt":"You edit LaTeX research papers. Make only the changes the instruction asks for. With no instruction, proofread: correct typos, grammar and LaTeX formatting, and leave the claims, the mathematics and the authors'' style as they are.\n\nWhen you write a LaTeX document:\n- Return each document complete, with every section in the order of the input.\n- Keep every LaTeX comment and every label; use the macros the preamble and the context files define, and do not redefine them.\n- Define notation and terminology before first use, and keep them consistent across the documents.\n- The document must stand on its own: its reader never sees this conversation."},"mediaFiles":[],"memories":[],"label":"Revision 1","prompt":"Read the following LaTeX research documents before editing them.\n\n<documents>\n<document name=\"paper.tex\">\n\\section{Input}\nThe golden edit program revises this file.\n\n</document>\n</documents>\n\nEdit the documents as the instruction asks, to the extent it asks: a proofread changes wording and formatting only, a polish may rewrite sentences and paragraphs for clarity and flow, and a request for new or expanded content adds it with every derivation step shown. Do not change text the instruction does not concern. Write plain technical English: concrete statements, plain verbs, each point made once.\n\nOutput the documents, complete and in this order, as:\n<documents>\n<document name=\"paper.tex\">\n...\n</document>\n</documents>"},"replay":"safe","logId":"00000000-0000-4000-8000-000000000034","section":"Revision 1"}}');
