INSERT INTO event VALUES(292,5,96,'plugin.fact',1,1767225892000,'{"plugin":"theory","kind":"output","version":5,"value":{"task":{"intro":"Read the following LaTeX research documents before editing them.","requests":["Edit the documents as the instruction asks, to the extent it asks: a proofread changes wording and formatting only, a polish may rewrite sentences and paragraphs for clarity and flow, and a request for new or expanded content adds it with every derivation step shown. Do not change text the instruction does not concern. Write plain technical English: concrete statements, plain verbs, each point made once.","Review your changes against the original and the instruction, then output the corrected documents. Revert any change the instruction did not ask for. Restore mathematics, equations or reasoning that went missing. Fix notation used before it is defined, and remove sentences that say nothing specific. If a change holds up, leave it alone; if nothing needs fixing, reproduce the documents unchanged."],"templates":[],"creates":false},"rounds":[{"round":0,"outputs":[{"source":"paper.polished.tex","location":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/r0/paper.polished.tex","relativePath":"r0/paper.polished.tex","runId":"a00000000005"},"round":0,"lineage":{"base":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/original/paper.tex","relativePath":"paper.tex","runId":"a00000000005"},"document":null},"diff":{"added":3,"removed":2}}],"compile":{"_tag":"checked","failures":[],"rejected":false},"missingOutputs":[],"latexdiffs":[{"revised":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/r0/paper.polished.tex","relativePath":"r0/paper.polished.tex","runId":"a00000000005"},"document":null,"base":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/original/paper.tex","relativePath":"paper.tex","runId":"a00000000005"},"baseRound":null,"mathMarkup":"coarse","status":"failed","error":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/original/paper.tex has no document environment (\\begin{document} … \\end{document})"}],"reply":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/r0/output.xml","relativePath":"r0/output.xml","runId":"a00000000005"}},{"round":1,"outputs":[{"source":"paper.polished.tex","location":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/r1/paper.polished.tex","relativePath":"r1/paper.polished.tex","runId":"a00000000005"},"round":1,"lineage":{"base":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/original/paper.tex","relativePath":"paper.tex","runId":"a00000000005"},"document":null},"diff":{"added":3,"removed":2}}],"compile":{"_tag":"checked","failures":[],"rejected":false},"missingOutputs":[],"latexdiffs":[{"revised":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/r1/paper.polished.tex","relativePath":"r1/paper.polished.tex","runId":"a00000000005"},"document":null,"base":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/original/paper.tex","relativePath":"paper.tex","runId":"a00000000005"},"baseRound":null,"mathMarkup":"coarse","status":"failed","error":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/original/paper.tex has no document environment (\\begin{document} … \\end{document})"}],"reply":{"kind":"runStorage","absolutePath":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/r1/output.xml","relativePath":"r1/output.xml","runId":"a00000000005"}}],"diffs":[{"path":"/golden/home/.texra/v1/workspace-storage/project-golden/executions/a00000000005/r1/paper.polished.tex","diffRelPath":"diffs/r1_paper.polished.tex.diff","largeChange":true}]}}');
