INSERT INTO event VALUES(301,8,3,'model.message',22,1767225901000,'{"payload":{"kind":"append","messages":[{"role":"user","content":[{"kind":"text","text":"Start the golden chat."}]}],"sourceResponse":null,"input":{"system":"0384bbc644fd6383ce329e9a6f6d0ed038e9bbffa5c80610e66ecb44ae75c800"}}}');
INSERT INTO event VALUES(302,8,4,'context.blob',1,1767225902000,'{"payload":{"digest":"0384bbc644fd6383ce329e9a6f6d0ed038e9bbffa5c80610e66ecb44ae75c800","value":"\"GOLDEN-CHAT: plan, run the plan as a goal, complete it.\\n<tool_use_instructions>\\nWorking directory: the bash tool already executes every command from /golden/project. You are already in the workspace, so run commands directly with relative paths (e.g., `ls src/`, `cat README.md`). Scope file searches to `.` or a subdirectory, or use the glob/grep tools.\\nExplicit user constraints override general workflow guidance elsewhere in the agent prompt. If the user forbids memory, planning, file access, or a tool, do not use it. Report any resulting conflict instead.\\n\\nPrefer using tools over asking the user to take manual actions.\\nDo not ask for permission in chat before editing a file or running a command: when the user''s approval settings require confirmation, the harness asks before the call runs.\\nIf you say you will perform an action, immediately call the corresponding tool.\\nDo only what the task requires. Do not refactor, restructure, or \\\"improve\\\" material beyond it. When the user describes a problem without asking for a change, deliver your assessment before editing files.\\nWhen this run carries out an approved plan or a goal''s round, work toward it end to end. Keep going and verify against real evidence rather than pausing to confirm each step or summarize progress. Stop only when it is verifiably done or you are genuinely blocked on something only the user can provide.\\nIn replies, lead with the outcome. Keep responses short by being selective about what to include, not by compressing the writing.\\nNever mention tool names when speaking to the user.\\n</tool_use_instructions>\\n\\n<workspace_info>\\nWorkspace: /golden/project\\nPlatform: golden\\nShell: golden\\nDate: 2026-01-01\\nGit: this workspace is not a git work tree, or git could not be checked; confirm a repository exists before running git history or status checks.\\n</workspace_info>\""}}');
INSERT INTO event VALUES(303,8,5,'context.blob',1,1767225903000,'{"payload":{"digest":"511439ab1e9f0a075420f2aebc6a3b807ba54090dd4ef04ca98e14680f2a2f98","value":"\"GOLDEN-CHAT: plan, run the plan as a goal, complete it.\\n<tool_use_instructions>\\nWorking directory: the bash tool already executes every command from /golden/project. You are already in the workspace, so run commands directly with relative paths (e.g., `ls src/`, `cat README.md`). Scope file searches to `.` or a subdirectory, or use the glob/grep tools.\\nExplicit user constraints override general workflow guidance elsewhere in the agent prompt. If the user forbids memory, planning, file access, or a tool, do not use it. Report any resulting conflict instead.\\n\\nPrefer using tools over asking the user to take manual actions.\\nDo not ask for permission in chat before editing a file or running a command: when the user''s approval settings require confirmation, the harness asks before the call runs.\\nIf you say you will perform an action, immediately call the corresponding tool.\\nDo only what the task requires. Do not refactor, restructure, or \\\"improve\\\" material beyond it. When the user describes a problem without asking for a change, deliver your assessment before editing files.\\nWhen this run carries out an approved plan or a goal''s round, work toward it end to end. Keep going and verify against real evidence rather than pausing to confirm each step or summarize progress. Stop only when it is verifiably done or you are genuinely blocked on something only the user can provide.\\nIn replies, lead with the outcome. Keep responses short by being selective about what to include, not by compressing the writing.\\nNever mention tool names when speaking to the user.\\n</tool_use_instructions>\\n\\n<workspace_info>\\nWorkspace: /golden/project\\nPlatform: golden\\nShell: golden\\nDate: 2026-01-01\\nGit: this workspace is not a git work tree, or git could not be checked; confirm a repository exists before running git history or status checks.\\n</workspace_info>\\nIndependent tool calls may be issued together in one response. Sequence only calls that depend on an earlier result.\\nDo not create excessive markdown files or documentation unless explicitly requested.\\nFind the project''s TeX sources with relative paths (e.g., `find . -name \\\"*.tex\\\"`).\\nFor math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\\n<memory_tool_instructions>\\nPinned memories apply to every session unless the user forbids memory use, and nothing loads them for you. At session start, `view` the `/memories` directory to find entries marked [pinned]. If the listing is truncated, continue until you have seen every [pinned] entry. Then `view` each pinned file so its content applies, regardless of how self-contained the request looks. Pinned entries are the core reusable insights (techniques, strategies, pitfalls) accumulated across sessions. The directory listing alone does not load their content. Beyond pinned entries, use memory when the request may depend on prior sessions, durable user preferences, or shared agent context. For a self-contained request, do not read unpinned memory files or write memory merely because the tool is available. Listing the directory is still appropriate because it is needed to find pinned entries.\\n\\nYour memory persists across conversations. When memory is in play, record durable progress, decisions, and user preferences (writing style, conventions, formatting, workflow). Keep the folder current and organized by updating, renaming, or deleting files rather than duplicating them. Do not store what the workspace files already state. Use `pin` only for long-term reusable insights, never task-specific progress notes. Use `unpin` for entries that no longer earn their place.\\n</memory_tool_instructions>\""}}');
INSERT INTO event VALUES(304,8,6,'context.blob',1,1767225904000,'{"payload":{"digest":"6fa1968f31eea2b2a4e12f6639c351507946d53856fcfe0c88cde52d1d0c3095","value":"{\"sections\":{\"core plugin\":\"Find the project''s TeX sources with relative paths (e.g., `find . -name \\\"*.tex\\\"`).\\nFor math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\",\"memory-workflow plugin\":\"<memory_tool_instructions>\\nPinned memories apply to every session unless the user forbids memory use, and nothing loads them for you. At session start, `view` the `/memories` directory to find entries marked [pinned]. If the listing is truncated, continue until you have seen every [pinned] entry. Then `view` each pinned file so its content applies, regardless of how self-contained the request looks. Pinned entries are the core reusable insights (techniques, strategies, pitfalls) accumulated across sessions. The directory listing alone does not load their content. Beyond pinned entries, use memory when the request may depend on prior sessions, durable user preferences, or shared agent context. For a self-contained request, do not read unpinned memory files or write memory merely because the tool is available. Listing the directory is still appropriate because it is needed to find pinned entries.\\n\\nYour memory persists across conversations. When memory is in play, record durable progress, decisions, and user preferences (writing style, conventions, formatting, workflow). Keep the folder current and organized by updating, renaming, or deleting files rather than duplicating them. Do not store what the workspace files already state. Use `pin` only for long-term reusable insights, never task-specific progress notes. Use `unpin` for entries that no longer earn their place.\\n</memory_tool_instructions>\",\"tool-call\":\"Independent tool calls may be issued together in one response. Sequence only calls that depend on an earlier result.\\nDo not create excessive markdown files or documentation unless explicitly requested.\"},\"tools\":[\"plan\",\"codex\",\"bash\",\"memory\",\"context\"]}"}}');
INSERT INTO event VALUES(305,8,7,'context.blob',1,1767225905000,'{"payload":{"digest":"b3b2a3d44f4a95de0455196ad7ead418771471fafd4c8ed975d4774b7c4fe2a1","value":"{\"description\":\"Propose or replace the plan: `objective` is a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Every proposal is presented to the user, who may approve it, run it as a goal (a goal run then works on it in rounds until it verifies the stopping condition), or reject it. Propose a new plan only when the objective or approach genuinely changes.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"objective\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(306,8,8,'context.blob',1,1767225906000,'{"payload":{"digest":"d9362d87c2e2a7abe053247649f3a41e0c9a2b06dc02a63b32b890074f9f4996","value":"{\"description\":\"Spin off an OpenAI Codex agent to perform code analysis, generation, or research in a sandboxed environment. The agent runs the Codex CLI locally and can read files, run commands, and make edits within its sandbox, which follows this run''s approval policy: workspace-write when the launch was approved, full access under Auto-approve or an all-agent-work grant. Auth is handled by the CLI itself: use `codex login` (OAuth, recommended) or set OPENAI_API_KEY env var. Always async: returns immediately with a run ID; each turn is delivered back as a follow-up message (including the thread_id). Pass thread_id on a later call to continue that thread with a follow-up instruction, one turn per call. Choose codex for coding tasks that benefit from a separate OpenAI agent. It runs in its own sandbox with independent tool use, async and multi-turn like `agent`. It runs in the working directory of the calling agent and takes no directory argument, so give parallel codex agents disjoint files to edit. codex and claude_code are both independent sandboxed coders distinct from the in-process `agent` specialists. Prefer whichever vendor fits the task.\",\"name\":\"codex\",\"parameters\":{\"properties\":{\"prompt\":{\"description\":\"Instruction for the Codex agent. For a new session, describe the task. For a resume (thread_id set), describe the follow-up.\",\"type\":\"string\"},\"thread_id\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Continue an existing Codex thread with a follow-up instruction, as its next turn. A thread whose turn is still running refuses another until that turn is delivered.\"}},\"required\":[\"prompt\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(307,8,9,'context.blob',1,1767225907000,'{"payload":{"digest":"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f","value":"{\"description\":\"Execute shell commands in the working directory (the project root, or the worktree the run is rooted in). Available environment variables: $PROJECT_DIR (that directory), $PROJECT_NAME (project name). Returns stdout on success, throws error with stderr on failure. Use run_in_background for long-running commands, with `timeout` raised to what they need.\",\"name\":\"bash\",\"parameters\":{\"properties\":{\"command\":{\"type\":\"string\"},\"description\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short description of what the command does, in 5-10 words (e.g. \\\"Run the unit tests\\\"). It names the call in the transcript and the background task list; execution ignores it.\"},\"run_in_background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Run command in background. Returns immediately with run ID and a background task tab. Result delivered as follow-up when complete; `timeout` still bounds the command.\"},\"timeout\":{\"anyOf\":[{\"maximum\":600000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Timeout in milliseconds (max 600,000 ms / 10 min, default 120,000 ms / 2 min).\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(308,8,10,'context.blob',1,1767225908000,'{"payload":{"digest":"2cf24576e72aa687df224a7a5037639917077bc04a67b4fef3ba72649d863a14","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are the ones to read at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"create\\\".\"},\"insert_line\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\".\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\": Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"new_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\" or \\\"insert\\\".\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"old_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\".\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted. With command \\\"create\\\", \\\"str_replace\\\", \\\"insert\\\", \\\"delete\\\", \\\"pin\\\", or \\\"unpin\\\": Path under /memories (e.g. /memories/notes.md).\"},\"view_range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\".\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(309,8,11,'context.blob',1,1767225909000,'{"payload":{"digest":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","value":"{\"description\":\"Read or edit your own context: the messages each of your requests sends.\\n\\n- view: each message with its index, role, kind, estimated tokens and a preview; the window size and the tokens in use; and the replacements this response already asked for.\\n- replace: messages [from, to) are replaced, before your next request, by one message holding `with`. Indices are the view''s, as this response was sent; ranges asked for in one response must not overlap. The range ends at or before the response that makes the call, and keeps each tool call with its results.\\n\\nThe replaced messages stay in the stored history: the person still sees them, and the executions tool, where offered, reads them back (/executions/current/conversation). A replacement ends prompt-cache reuse from its first message on, and any provider-side continuation, so the next request pays full input price for everything after that point. Keep what the user asked of you, in substance.\",\"name\":\"context\",\"parameters\":{\"properties\":{\"action\":{\"anyOf\":[{\"enum\":[\"view\",\"replace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"view\\\": Read the view (the default).\"},\"from\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index of the first message replaced.\"},\"to\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index after the last message replaced.\"},\"with\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": The text that stands in for those messages.\"}},\"type\":\"object\"}}"}}');
