INSERT INTO event VALUES(537,13,7,'context.blob',1,1767226137000,'{"payload":{"digest":"6e418fb15040d4b29421ec9a2946acb53ce350ccb8c8fb463b9303d660482e99","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(538,13,8,'context.blob',1,1767226138000,'{"payload":{"digest":"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f","value":"{\"description\":\"Execute shell commands in the working directory (the project root, or the worktree the run is rooted in). Available environment variables: $PROJECT_DIR (that directory), $PROJECT_NAME (project name). Returns stdout on success, throws error with stderr on failure. Use run_in_background for long-running commands, with `timeout` raised to what they need.\",\"name\":\"bash\",\"parameters\":{\"properties\":{\"command\":{\"type\":\"string\"},\"description\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short description of what the command does, in 5-10 words (e.g. \\\"Run the unit tests\\\"). It names the call in the transcript and the background task list; execution ignores it.\"},\"run_in_background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Run command in background. Returns immediately with run ID and a background task tab. Result delivered as follow-up when complete; `timeout` still bounds the command.\"},\"timeout\":{\"anyOf\":[{\"maximum\":600000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Timeout in milliseconds (max 600,000 ms / 10 min, default 120,000 ms / 2 min).\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
