INSERT INTO event VALUES(564,13,34,'context.blob',1,1767226164000,'{"payload":{"digest":"7336a63f4accc7244b17aeee518a84cfd1916d82abc50cd60781ad2b8bf4a4f7","value":"{\"agent\":\"eb97057094650ae43a9c988615d6a0d5ece9704858a8bf77ebd0f5e5705ff998\",\"controls\":{\"maxOutputTokens\":128000,\"promptCacheKey\":\"a0000000000d\",\"reasoning\":null,\"serviceTier\":null,\"store\":false,\"temperature\":0,\"toolChoice\":\"auto\"},\"mode\":\"foreground\",\"system\":\"b1344eb22d8a37f0cddb1f6beb9d48e74302cc277a7513c24b583557d773c70e\",\"tools\":[\"6e418fb15040d4b29421ec9a2946acb53ce350ccb8c8fb463b9303d660482e99\",\"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f\",\"6dcf7fae6de23f55f8665c11ce0196e6afc7885328332de7d332bc344ce87774\",\"0d96430c88daa0703070d54d751edc04b178818b177ec9f2aa2c598e7f0f5bfc\",\"2cf24576e72aa687df224a7a5037639917077bc04a67b4fef3ba72649d863a14\",\"b3b2a3d44f4a95de0455196ad7ead418771471fafd4c8ed975d4774b7c4fe2a1\",\"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675\"]}"}}');
INSERT INTO event VALUES(565,13,35,'model.message',22,1767226165000,'{"payload":{"kind":"attempt","invocation":{"invocationId":"00000000-0000-4000-8000-00000000006c","attempt":1},"request":"7336a63f4accc7244b17aeee518a84cfd1916d82abc50cd60781ad2b8bf4a4f7","origin":{"protocol":"openai-responses","requestedModel":"gpt-5.6-sol","deployment":{"endpoint":"https://validation.invalid/v1","credentialScope":"validation"},"codecVersion":1}}}');
INSERT INTO event VALUES(566,13,36,'model.message',22,1767226166000,'{"payload":{"kind":"response","responseId":"00000000-0000-4000-8000-00000000006d","invocation":{"invocationId":"00000000-0000-4000-8000-00000000006c","attempt":1},"turn":{"providerResponseId":"validation-response-1","requestedOrigin":{"protocol":"openai-responses","requestedModel":"gpt-5.6-sol","deployment":{"endpoint":"https://validation.invalid/v1","credentialScope":"validation"},"codecVersion":1},"returnedModel":"gpt-5.6-sol","content":[{"kind":"local-call","providerCallId":"validation-script-1","name":"script","argumentsText":"{\"title\":\"Gather the notes\",\"code\":\"section(''Gather'')\\nconst [found] = await searchTools(''read a file'', { limit: 1 })\\nconst declaration = await describeTool(found.name)\\nconst notes = await tools[found.name]({ path: ''notes.tex'' })\\nconst shell = await tools.bash({ command: ''echo gathered'', description: ''Say gathered'' })\\nreturn { found: found.name, documented: declaration.includes(''path: string''), notes: notes.output, shell: shell.output, defined: (await agent(''Answer from the notes.'', { agentName: ''golden_reader'', label: ''Defined agent'', persona: { prompt: ''GOLDEN-CHILD: answer the task.'', tools: [''read_file'', ''executions''] } })).response }\"}"}],"finishReason":"tool-calls","usage":{"inputTokens":1,"outputTokens":1,"totalTokens":2,"cachedInputTokens":null,"cacheWriteTokens":null,"reasoningTokens":null,"toolUsePromptTokens":null}},"calls":[{"callId":"validation-script-1","toolName":"script","lane":"barrier","replay":"safe","duplicateOf":null,"logId":"00000000-0000-4000-8000-00000000006e"}],"usage":{"inputTokens":1,"outputTokens":1,"cost":0.000024,"usageRoute":"api-key","responseTimeMs":0,"provider":"openai-responses"}}}');
