INSERT INTO event VALUES(725,19,7,'context.blob',1,1767226325000,'{"payload":{"digest":"6e418fb15040d4b29421ec9a2946acb53ce350ccb8c8fb463b9303d660482e99","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(726,19,8,'context.blob',1,1767226326000,'{"payload":{"digest":"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f","value":"{\"description\":\"Execute shell commands in the working directory (the project root, or the worktree the run is rooted in). Available environment variables: $PROJECT_DIR (that directory), $PROJECT_NAME (project name). Returns stdout on success, throws error with stderr on failure. Use run_in_background for long-running commands, with `timeout` raised to what they need.\",\"name\":\"bash\",\"parameters\":{\"properties\":{\"command\":{\"type\":\"string\"},\"description\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short description of what the command does, in 5-10 words (e.g. \\\"Run the unit tests\\\"). It names the call in the transcript and the background task list; execution ignores it.\"},\"run_in_background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Run command in background. Returns immediately with run ID and a background task tab. Result delivered as follow-up when complete; `timeout` still bounds the command.\"},\"timeout\":{\"anyOf\":[{\"maximum\":600000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Timeout in milliseconds (max 600,000 ms / 10 min, default 120,000 ms / 2 min).\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(727,19,9,'context.blob',1,1767226327000,'{"payload":{"digest":"6dcf7fae6de23f55f8665c11ce0196e6afc7885328332de7d332bc344ce87774","value":{"$b":"bad4275ec37b3002cde00b28dfe67cf2cc2e14f49615f09e8b0a09560a669c41"}}}');
INSERT INTO event VALUES(728,19,10,'context.blob',1,1767226328000,'{"payload":{"digest":"0d96430c88daa0703070d54d751edc04b178818b177ec9f2aa2c598e7f0f5bfc","value":{"$b":"5e8fe360cce30b345c5547dcd8d691d22524472817b08476319f148184d85d05"}}}');
INSERT INTO event VALUES(729,19,11,'context.blob',1,1767226329000,'{"payload":{"digest":"2cf24576e72aa687df224a7a5037639917077bc04a67b4fef3ba72649d863a14","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are the ones to read at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"create\\\".\"},\"insert_line\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\".\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\": Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"new_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\" or \\\"insert\\\".\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"old_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\".\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted. With command \\\"create\\\", \\\"str_replace\\\", \\\"insert\\\", \\\"delete\\\", \\\"pin\\\", or \\\"unpin\\\": Path under /memories (e.g. /memories/notes.md).\"},\"view_range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\".\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(730,19,12,'context.blob',1,1767226330000,'{"payload":{"digest":"b3b2a3d44f4a95de0455196ad7ead418771471fafd4c8ed975d4774b7c4fe2a1","value":"{\"description\":\"Propose or replace the plan: `objective` is a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Every proposal is presented to the user, who may approve it, run it as a goal (a goal run then works on it in rounds until it verifies the stopping condition), or reject it. Propose a new plan only when the objective or approach genuinely changes.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"objective\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(731,19,13,'context.blob',1,1767226331000,'{"payload":{"digest":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","value":"{\"description\":\"Read or edit your own context: the messages each of your requests sends.\\n\\n- view: each message with its index, role, kind, estimated tokens and a preview; the window size and the tokens in use; and the replacements this response already asked for.\\n- replace: messages [from, to) are replaced, before your next request, by one message holding `with`. Indices are the view''s, as this response was sent; ranges asked for in one response must not overlap. The range ends at or before the response that makes the call, and keeps each tool call with its results.\\n\\nThe replaced messages stay in the stored history: the person still sees them, and the executions tool, where offered, reads them back (/executions/current/conversation). A replacement ends prompt-cache reuse from its first message on, and any provider-side continuation, so the next request pays full input price for everything after that point. Keep what the user asked of you, in substance.\",\"name\":\"context\",\"parameters\":{\"properties\":{\"action\":{\"anyOf\":[{\"enum\":[\"view\",\"replace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"view\\\": Read the view (the default).\"},\"from\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index of the first message replaced.\"},\"to\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index after the last message replaced.\"},\"with\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": The text that stands in for those messages.\"}},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(732,19,14,'context.blob',1,1767226332000,'{"payload":{"digest":"c3873f6f8ddca05d9eb63f7b643e986232b98fb0c9cbe9755ff969d692cb1f4e","value":"{\"description\":\"Run yourself again on a prompt, as a child of this call, and wait for its result: `{ response, files, structured?, runId, outcome, cost, spent }`, as `agent()` resolves.\\n\\nForked (the default), the child continues this conversation as it stood when the script started (the message of the turn that started it, not that turn''s work so far), with `prompt` added to that message; with `fork: false` it starts with no earlier conversation. Either way the child is told `prompt` is the one part of the script''s work it does, and not to take on the rest. It is you with your tools, and nothing is proposed or approved again. It runs on your model unless `model` names another, which is how a different model checks a result with your prompt and tools; a fork takes only a model that can continue this conversation, and a model with another conversation format takes `fork: false`.\\n\\nIt rejects with an Error named `AgentFailed`, `TimedOut` (past `timeoutMs`), `BudgetExceeded` (the child and the runs it started spent `maxCostUsd` before it finished; the cap is read after each reply, so the spend can pass it by the replies then in flight), `Skipped` (the user stopped it) or `ModelUnavailable`. Call it from a script; called directly, it runs nothing.\",\"name\":\"self\",\"parameters\":{\"properties\":{\"fork\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Continue this conversation as it stood when the script started, with `prompt` added to the message that started it; `false` starts with no earlier conversation. Either way the child is told `prompt` is the one part of the work it does.\"},\"label\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short title for the call’s card.\"},\"maxCostUsd\":{\"anyOf\":[{\"exclusiveMinimum\":0,\"type\":\"number\"},{\"type\":\"null\"}],\"description\":\"A spend cap in USD on the child and every run it starts: once they have spent it, the child is stopped: `BudgetExceeded`. Only for a call that waits for its child.\"},\"model\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Model reference, `@effort` suffix allowed (`@low` … `@max`, `@none`). Defaults to your current model when available.\"},\"prompt\":{\"description\":\"What this run of you works on.\",\"minLength\":1,\"type\":\"string\"},\"schema\":{\"anyOf\":[{\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"A JSON Schema object: the run finishes by submitting a value of it, returned as `structured`.\"},\"timeoutMs\":{\"anyOf\":[{\"maximum\":86400000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Stops the child after this many milliseconds: `TimedOut`. Only for a call that waits for its child.\"}},\"required\":[\"prompt\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(733,19,15,'context.blob',1,1767226333000,'{"payload":{"digest":"e7cd4e81487996332ca7fa71690f86ff6eb66f49776b2dc361b54339db62b5cc","value":{"$b":"774f99b1ac4c3c3346e45a4b6b45efea922c89d08d57295eb8ffff5963cedef4"}}}');
INSERT INTO event VALUES(734,19,16,'context.blob',1,1767226334000,'{"payload":{"digest":"1f30ef04c6e89fb6d45afa72306deb4860b05d77c33c0056c10da7eef312f9a1","value":"\"export const rounds = async (\\n  { name, system, tools, rounds, extension, describes, fallback, check },\\n  { instruction, inputFiles, contextFiles },\\n) => {\\n  const files = inputFiles.filter((file) => file.endsWith(extension));\\n  const skipped = inputFiles.filter((file) => !file.endsWith(extension));\\n  if (files.length === 0)\\n    throw new Error(name + '' works on '' + extension + '' files: pass '' + describes + '' as inputFiles.'');\\n  const task = [\\n    instruction.trim() ? ''<instruction>\\\\n'' + instruction.trim() + ''\\\\n</instruction>'' : fallback,\\n    ''The files: '' + files.join('', '') + ''.'',\\n    ...(contextFiles.length > 0 ? [''Read these for context and do not change them: '' + contextFiles.join('', '') + ''.''] : []),\\n  ].join(''\\\\n\\\\n'');\\n  // A file the program does not work on is named, never dropped unsaid.\\n  const answer = (verdict, reply) =>\\n    [verdict, ...(skipped.length > 0 ? [''Not '' + extension + '' files, so not worked on: '' + skipped.join('', '') + ''.''] : []), reply].join(''\\\\n\\\\n'');\\n  let checked = null;\\n  let reply = null;\\n  for (let round = 1; round <= rounds; round += 1) {\\n    const label = ''Round '' + round;\\n    section(label);\\n    const prompt = checked === null ? task : task + ''\\\\n\\\\nAn earlier round left work to do. The check reports:\\\\n'' + checked.report;\\n    reply = await agent(prompt, { agentName: name, persona: { prompt: system, tools }, label, id: ''round-'' + round });\\n    checked = await check(files);\\n    if (checked.clean) return answer(checked.report, reply.response);\\n  }\\n  return answer(''After '' + rounds + '' rounds the check still reports:\\\\n'' + checked.report, reply.response);\\n};\""}}');
INSERT INTO event VALUES(735,19,17,'context.blob',1,1767226335000,'{"payload":{"digest":"58a7f422dff3d1dbbfb948d7f471612e6401cdc5ea9d68fa6fe28872db3fef34","value":{"$b":"4338b0957b2c9831e8cee571058fbf1490c067843f77f60d9bfdd1f383acf152"}}}');
INSERT INTO event VALUES(736,19,18,'context.blob',1,1767226336000,'{"payload":{"digest":"84addbb9705fdffb67713ca30525890fb3da2dfcfc34030cc79e4ae62b120f94","value":"\"import { rounds } from ''builtIn:rounds'';\\n\\nconst WRITER = [\\n  ''You write and maintain formalization blueprints: LaTeX documents, built with the leanblueprint package and its CLI, that split a proof into small statements with explicit dependencies and link each to its Lean declaration. Follow the package\\\\''s own macros and the file layout leanblueprint new creates; invent no parallel conventions.'',\\n  ''The macros. Inside a definition, lemma, proposition, theorem or corollary, each with a \\\\\\\\label: \\\\\\\\lean{Name.decl} links Lean declarations (comma-separated), \\\\\\\\leanok marks the statement formalized, \\\\\\\\mathlibok marks it in Mathlib, \\\\\\\\uses{label, ...} lists the statements it depends on, and \\\\\\\\notready marks one that needs more blueprint work. Inside a proof: \\\\\\\\uses{...} for what the proof relies on, \\\\\\\\leanok when the proof is formalized, and \\\\\\\\proves{label} for a proof separated from its statement.'',\\n  ''Write the mathematics as a paper does, in standard notation: no Lean syntax, identifiers or type signatures in the prose. A Lean predicate becomes a sentence, a typeclass assumption becomes \\\"let G be a group\\\", a type becomes the set it stands for. \\\\\\\\lean{} is the only place a Lean name appears. Refer to statements by \\\\\\\\ref to their labels, never by number. Each statement states its hypotheses in full; a proof sketch gives the strategy in a sentence or two, enough for a formalizer to follow.'',\\n  ''To write a new blueprint, survey the Lean project first, then design the dependency graph backward from the main results: each node one well-defined fact. To bring an existing one up to date, check every \\\\\\\\lean name against the source (renamed or removed declarations), every \\\\\\\\leanok against lean_diagnostics (no error, no sorry; call lean_file on a Lean file first, since Lean reads a file only when it opens it), every statement against its declaration\\\\''s type (lean_inspect hover), and every \\\\\\\\uses against what the proof actually relies on; add entries for significant declarations the blueprint lacks. Before you answer, run leanblueprint web and leanblueprint checkdecls and fix what they report: the program checks your work with the same two commands.'',\\n  ''Your answer goes to the person who started the program: what you wrote or changed, what is out of sync or mathematically suspect, and what you left for them.'',\\n].join(''\\\\n\\\\n'');\\n\\n/** What leanblueprint itself checks: the blueprint builds, and every\\n *  \\\\lean name is a declaration of the built project. */\\nconst CHECK = ''leanblueprint web && leanblueprint checkdecls'';\\n\\nexport default async (args, launch) => {\\n  // A missing CLI fails the launch before any round is paid for.\\n  try {\\n    await tools.bash({ command: ''leanblueprint --version'' });\\n  } catch {\\n    throw new Error(''blueprint checks its work with the leanblueprint CLI, which is not installed: pip install leanblueprint.'');\\n  }\\n  return rounds(\\n    {\\n      name: ''blueprint'',\\n      system: WRITER,\\n      tools: [''read_file'', ''write_file'', ''edit_file'', ''glob'', ''grep'', ''bash'', ''lean_diagnostics'', ''lean_inspect'', ''lean_file'', ''lean_loogle'', ''web_search'', ''web_fetch'', ''arxiv_search''],\\n      rounds: 2,\\n      extension: ''.tex'',\\n      describes: \\\"the blueprint''s .tex files (a project without one starts with leanblueprint new)\\\",\\n      fallback: ''Bring this blueprint up to date with the Lean project.'',\\n      check: async () => {\\n        try {\\n          await tools.bash({ command: CHECK, timeout: 600000 });\\n          return { clean: true, report: ''The blueprint builds, and leanblueprint checkdecls finds every \\\\\\\\lean declaration.'' };\\n        } catch (failure) {\\n          return { clean: false, report: CHECK + '' failed:\\\\n'' + failure.message };\\n        }\\n      },\\n    },\\n    launch,\\n  );\\n};\""}}');
INSERT INTO event VALUES(737,19,19,'context.blob',1,1767226337000,'{"payload":{"digest":"719b092481bd38710c043158937494f7ae2c77b4ceed802f65e8b1fa3b519fe3","value":{"$b":"fe322a049574403d857b7cda3e7f0f053262530937805a1c9609a532c3dc1bf6"}}}');
INSERT INTO event VALUES(738,19,20,'context.blob',1,1767226338000,'{"payload":{"digest":"eccb21f98820b758176f40717fd832cf5a7dd5f20170b32ff5ef7a195420dfe0","value":"\"import { revise, LATEX } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''edit'',\\n    system: ''You edit LaTeX research papers. Make only the changes the instruction asks for. With no instruction, proofread: correct typos, grammar and LaTeX formatting, and leave the claims, the mathematics and the authors\\\\'' style as they are.\\\\n\\\\n'' + LATEX,\\n    intro: ''Read the following LaTeX research documents before editing them.'',\\n    requests: [\\n      ''Edit the documents as the instruction asks, to the extent it asks: a proofread changes wording and formatting only, a polish may rewrite sentences and paragraphs for clarity and flow, and a request for new or expanded content adds it with every derivation step shown. Do not change text the instruction does not concern. Write plain technical English: concrete statements, plain verbs, each point made once.'',\\n      ''Review your changes against the original and the instruction, then output the corrected documents. Revert any change the instruction did not ask for. Restore mathematics, equations or reasoning that went missing. Fix notation used before it is defined, and remove sentences that say nothing specific. If a change holds up, leave it alone; if nothing needs fixing, reproduce the documents unchanged.'',\\n    ],\\n  });\""}}');
INSERT INTO event VALUES(739,19,21,'context.blob',1,1767226339000,'{"payload":{"digest":"4f0223c81f96b2081bc6e1e9d31e786592118d34354647d3fb51d4d07655b3cf","value":"\"import { revise, addsOnly, ANNOTATIONS, CRITICIZE } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''annotate'',\\n    system: ''You review research papers by adding \\\\\\\\criticize annotations to them. You never rewrite: outside your annotations, every document you return is the input, character for character.'',\\n    intro: ''The following LaTeX documents need review. Read every document, appendices included, before you annotate.'',\\n    requests: [\\n      ''Review the documents from the point of view the instruction names; with none, as a careful referee of the mathematics. Work through each derivation and claim yourself before you judge it, and annotate every point that needs action: errors, gaps, unsupported or overstated claims, undefined terms, and inconsistencies between the documents. Rate each by its severity and your confidence. Return every document complete, with your annotations inserted and nothing else changed.\\\\n\\\\n'' + ANNOTATIONS,\\n      ''Check each annotation you added: verify the claim behind it again, correct its severity and confidence, remove the ones that do not hold, and add any you missed. Return every document complete, with the annotations inserted and nothing else changed.'',\\n    ],\\n    // What a prompt can only ask for, checked: the diff adds annotations only.\\n    verify: addsOnly(''\\\\\\\\criticize'', CRITICIZE),\\n  });\""}}');
INSERT INTO event VALUES(740,19,22,'context.blob',1,1767226340000,'{"payload":{"digest":"9ad7e68fe5a5c22f89a4f183118792f80e336d5554318dca65314d5b56d9793a","value":"\"import { revise, LATEX, ANNOTATIONS } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''enhance'',\\n    system: ''You improve the substance of research papers: you make the improvements you can carry out in full, and leave a \\\\\\\\criticize annotation where an improvement needs the authors.\\\\n\\\\n'' + LATEX,\\n    intro: ''The following LaTeX documents need improvement. Read the full collection, appendices included, before you change anything.'',\\n    requests: [\\n      ''Improve the documents in the respect the instruction names (for example the mathematical content, the logical structure of the argument, or the consistency of the notation); with none, look for simpler proofs, stronger results and gaps in the mathematics. Make each improvement you can carry out completely and correctly, showing every step of new mathematics. Where an improvement is larger than you can finish, or needs a decision from the authors, leave the text as it is and add an annotation that starts with \\\"Suggestion:\\\". Mark each change you made with an annotation that starts with \\\"Implemented:\\\".\\\\n\\\\n'' + ANNOTATIONS,\\n      ''Verify every change you made: rederive new mathematics step by step, check that each change is consistent with the rest of the documents, and revert any that does not hold. Then output the complete documents.'',\\n    ],\\n  });\""}}');
INSERT INTO event VALUES(741,19,23,'context.blob',1,1767226341000,'{"payload":{"digest":"8d1b0387d8f107cae44916df911979f0876891e9fb650e68c8eb43baae145b92","value":"\"import { revise, LATEX } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''apply'',\\n    system: ''You implement the fixes that inline annotations from an earlier review ask for (\\\\\\\\criticize{comment}{severity}{confidence}, \\\\\\\\todo{}, \\\\\\\\comment{} or % comments). The instruction decides which annotations to handle; with none, handle them all. Understand each issue, work through any mathematics it needs, and apply the fix; remove an annotation once it is handled or when its severity is 0.\\\\n\\\\n'' + LATEX,\\n    intro: ''The following LaTeX documents contain inline annotations from an earlier review. Read every document and locate every annotation.'',\\n    requests: [\\n      ''Apply the annotations: correct errors directly, write out missing steps and derivations in full, rewrite unclear passages in plain technical English, and resolve inconsistencies between the documents to one version. Do not use notation before the document defines it. Leave an annotation in place, unchanged, when the instruction excludes it or you cannot resolve it. Output the complete documents.'',\\n    ],\\n  });\""}}');
INSERT INTO event VALUES(742,19,24,'context.blob',1,1767226342000,'{"payload":{"digest":"3c4734068992228f070d7a71c8cd359031dc1e9c726efbfbf1af34ab58f6b846","value":"\"import { revise } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''merge'',\\n    system: ''You merge the changes of an edited LaTeX document into its original. You keep the original\\\\''s structure and formatting and incorporate every edit.'',\\n    intro: ''Create one complete LaTeX document from the original document and its edited version below. Keep the original\\\\''s structure, so that a diff of the two versions shows only the edits.'',\\n    requests: [\\n      ''Where the edited version says a part is unchanged or leaves it out, copy that part from the original verbatim. Where it shows an edit or an addition, incorporate it exactly as written, in place of the corresponding part of the original. Keep every section header, equation, figure, table, macro and comment in its place; where the edited version is ambiguous, keep the original. Before you answer, check that every edit is in and nothing else changed. Output the complete merged document.'',\\n    ],\\n  });\""}}');
INSERT INTO event VALUES(743,19,25,'context.blob',1,1767226343000,'{"payload":{"digest":"ca2bab7d16eb65978a6096dcbf152fbb81da51481b0885923610dd8b477fde38","value":"\"import { revise } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''transcribe'',\\n    creates: true,\\n    system: ''You turn attached media into LaTeX. Images of handwriting or scans are pages of one text, in the order given: you write their content in the notation and style of the context documents. Recordings are one session, in the order given: you transcribe the spoken words with speakers and timestamps, a short opening summary and logical sections, and write spoken mathematics as LaTeX equations.'',\\n    intro: ''Transcribe the attached media into one LaTeX document that compiles on its own. Any documents below are context for its notation and style.'',\\n    requests: [\\n      ''Write the document. For images, use the document class, notation, environments and symbols of the context documents when there are any. For a recording, open with a short summary of the topics, then write each utterance as \\\"[HH:MM:SS] Speaker: text\\\", grouped into sections; do not use markdown.'',\\n      ''Review your transcription against the media and output the final document. For images, fix symbols you misread or that differ from the context documents\\\\'' notation, subscripts and superscripts, and environments. For a recording, fix misheard words, speaker labels, timestamps and equations.'',\\n    ],\\n  });\""}}');
INSERT INTO event VALUES(744,19,26,'context.blob',1,1767226344000,'{"payload":{"digest":"2840e2bd703d7808b08c7d455dda611387d34e318ebc82ec785b0fd958789204","value":"\"import { revise } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''slides'',\\n    creates: true,\\n    templates: [''template_slide.tex''],\\n    system: ''You turn research papers into LaTeX Beamer presentations for a scientific audience. Each slide makes one point; every bullet states a specific fact, method or result in plain words.'',\\n    intro: ''Create a LaTeX Beamer presentation from the research paper below. Use the template among the documents as its skeleton.'',\\n    requests: [\\n      ''Write a complete, self-contained deck of 10 to 15 slides: introduction, the paper\\\\''s methods and key results with their equations, and a conclusion slide. Follow the instruction when there is one.'',\\n      ''Review the draft deck for the accuracy of the paper\\\\''s claims, slide organization, equation formatting and plain, concrete phrasing. Fix what you find and output the complete deck; if nothing needs fixing, reproduce it unchanged.'',\\n    ],\\n  });\""}}');
INSERT INTO event VALUES(745,19,27,'context.blob',1,1767226345000,'{"payload":{"digest":"ef65ae9a87b41ff6004d7401d8e8209c8baa33e27521a4d58b1bec28ed82b534","value":"\"import { revise } from ''builtIn:revise'';\\n\\nexport default (args) =>\\n  revise({\\n    ...args,\\n    name: ''poster'',\\n    creates: true,\\n    templates: [''template_poster.tex'', ''beamercolorthemempi.sty'', ''beamerthemeconfposter.sty''],\\n    system: ''You turn research papers into mathematically detailed LaTeX Beamer posters for a scientific audience, written plainly and concretely.'',\\n    intro: ''Create a LaTeX Beamer poster from the research paper below. Use the poster template among the documents as its skeleton, with the template\\\\''s theme and color scheme.'',\\n    requests: [\\n      ''Write a complete, self-contained poster with clear sections (abstract, introduction, framework, methods, results, discussion, conclusions), the paper\\\\''s key equations and derivations, and compact references. Follow the instruction when there is one.'',\\n      ''Review the draft poster for mathematical accuracy, readability at poster size, compact references, use of the template\\\\''s color scheme and plain, concrete phrasing. Fix what you find and output the complete poster; if nothing needs fixing, reproduce it unchanged.'',\\n    ],\\n  });\""}}');
